<?php require 'auth.php';$p=db();if($_SERVER['REQUEST_METHOD']==='POST')$p->prepare('UPDATE orders SET order_status=? WHERE id=?')->execute([$_POST['order_status'],(int)$_POST['id']]);$os=$p->query('SELECT * FROM orders ORDER BY id DESC')->fetchAll();$title='Manage Orders - '.APP_NAME;include '../includes/header.php';?><div class="page-heading"><div><h1>Orders</h1><p>Track payments and update the fulfilment status of customer orders.</p></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Payment</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($os as $o):?><tr><td><strong>#<?=$o['id']?></strong><br><small style="color:#64748b"><?=htmlspecialchars($o['created_at'])?></small></td><td><?=htmlspecialchars($o['customer_name'])?><br><small style="color:#64748b"><?=htmlspecialchars($o['phone'])?></small></td><td><strong>KES <?=number_format($o['total'],2)?></strong></td><td><span class="badge <?=$o['payment_status']==='Paid'?'badge-green':($o['payment_status']==='Failed'?'badge-red':'badge-orange')?>"><?=htmlspecialchars($o['payment_status'])?></span></td><td><span class="badge badge-blue"><?=htmlspecialchars($o['order_status'])?></span></td><td><form method="post" style="display:flex;gap:7px;min-width:220px"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="order_status" style="flex:1;padding:9px;border:1px solid #d7dce5;border-radius:8px"><?php foreach(['Pending','Processing','Ready','Shipped','Completed','Cancelled'] as $st):?><option <?=$o['order_status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select><button class="admin-btn" style="padding:9px 12px">Save</button></form></td></tr><?php endforeach;?></tbody></table><?php if(!$os):?><div class="empty">No orders yet.</div><?php endif;?></div><?php include '../includes/footer.php';?>
